style.css:
@-moz-document url-prefix("https://www.reddit.com/") {
#flex-nav-collapse-button{
 border-width:1px !important;
 box-shadow:0px -2px 7px -3px rgba(5,255,205,0.38) inset;
 border-color:rgba(127,255,231,0.35);
}

.pt-\[var\(--page-y-padding\)\] .flex-nav-expanded{
 background-image:linear-gradient(-180deg, #ffffff 0%, #5bd3ff 100%);
 background-attachment:fixed;
 background-size:contain;
}

.pt-\[var\(--page-y-padding\)\] .theme-beta header{
 background-image:linear-gradient(-180deg, #ffffff 0%, #c6eeff 48%, #a3e0ff 50%, #89dfff 100%);
 transform:translatex(0px) translatey(0px);
}

#reddit-logo .items-center .h-\[22px\]{
 box-shadow:none;
 border-top-left-radius:0px;
 border-top-right-radius:0px;
}

.m\:pointer-events-auto .w-\[inherit\]{
 box-shadow:0px 0px 44px -50px #333d42 inset;
}

#left-sidebar{
 background-image:linear-gradient(-90deg, rgba(15,184,173,0) 0%, #c2fefb 100%);
 background-position-y:0%;
 background-position-x:0%;
 backdrop-filter: saturate(0);
 background-color:rgba(255,255,255,0);
}

#right-sidebar-contents .flex-col .nd\:bg-neutral-background-weak{
 transform:translatex(0px) translatey(0px);
 background-color:transparent;
}

#advertise-button{
 box-shadow:0px -2px 7px -3px rgba(5,255,205,0.38) inset;
 border-color:rgba(127,255,231,0.35);
 background-color:#ffffff;
}

#header-action-item-chat-button{
 box-shadow:0px -2px 7px -3px rgba(5,255,205,0.38) inset;
 border-color:rgba(127,255,231,0.35);
 background-color:#ffffff;
}

#create-post{
 box-shadow:0px -2px 7px -3px #ff9205 inset;
 border-color:rgba(127,255,231,0.35);
 background-color:#ffffff;
}

#notifications-inbox-button{
 box-shadow:0px -2px 7px -3px rgba(5,255,205,0.38) inset;
 border-color:rgba(127,255,231,0.35);
 background-color:#ffffff;
}

#main-content .w-full a.absolute{
 box-shadow:0px 0px 19px 0px #65e2ff inset;
 border-top-left-radius:15px;
 border-top-right-radius:15px;
 border-bottom-left-radius:15px;
 border-bottom-right-radius:16px;
}

#left-sidebar .min-h-screen-without-header left-nav-top-section{
 box-shadow:0px -2px 12px -3px rgba(5,255,205,0.38) inset;
 border-color:rgba(127,255,231,0.35);
 border-top-left-radius:13px;
 border-top-right-radius:13px;
 border-bottom-left-radius:13px;
 border-bottom-right-radius:13px;
 color:#ffffff;
}

.focus-within\:bg-neutral-background-hover > .justify-between > .items-center{
 top:6px;
}

#main-content .pl-xs shreddit-post-overflow-menu{
 box-shadow:0px -2px 7px -3px rgba(5,255,205,0.38) inset;
 border-color:rgba(127,255,231,0.35);
 position:relative;
 left:-6px;
 top:10px;
}

#main-content ul .object-contain{
 box-shadow:0px 0px 50px 0px rgba(0,0,0,0.71) inset;
}

.gap shreddit-async-loader .nd\:visible .overflow-hidden > .flex-col{
 box-shadow:0px -2px 36px -3px rgba(5,255,205,0.38) inset;
 border-color:rgba(127,255,231,0.35);
 border-top-left-radius:0px;
 border-top-right-radius:0px;
}

.justify-end .flex create-post-entry-point-wrapper{
 box-shadow:none;
}

#flex-left-nav-container{
 background-color:rgba(0,0,0,0) !important;
 transform:translatex(0px) translatey(0px);
}

#comment-tree .relative > .overflow-hidden{
 background-color:rgba(255,255,255,0.64);
}

#subgrid-container{
 box-shadow:0px 0px 50px 0px #89dfff inset;
 border-top-left-radius:11px;
 border-top-right-radius:11px;
 border-bottom-left-radius:11px;
 border-bottom-right-radius:11px;
 border-width:1px;
 border-color:rgba(127,255,231,0.35);
 border-style:solid;
 background-color:#f7f7f7;
 transform:translatex(0px) translatey(0px);
}

#main-content shreddit-async-loader .bg-\[color\:var\(--shreddit-content-background\)\] > .items-center{
 border-top-left-radius:14px;
 border-top-right-radius:14px;
 border-bottom-left-radius:14px;
 border-bottom-right-radius:14px;
 box-shadow:0px 0px 19px 0px #0e0f0c;
}

#main-content .nd\:hidden faceplate-tracker .w-full{
 border-top-left-radius:14px;
 border-top-right-radius:14px;
 border-bottom-left-radius:14px;
 border-bottom-right-radius:14px;
 box-shadow:0px 0px 18px 0px #0e0f0c;
}

#comment-tree > .relative{
 border-top-left-radius:14px;
 border-top-right-radius:14px;
 border-bottom-left-radius:14px;
 border-bottom-right-radius:14px;
 transform:translatex(0px) translatey(0px);
 box-shadow:0px 0px 21px 0px #333d42;
}

#comment-tree .relative > .nd\:hidden{
 box-shadow:none;
}

#comment-tree .relative .rte-media{
 box-shadow:none;
}

#main-content .xs\:-mx-xs{
 box-shadow:0px 0px 19px 0px #333d42;
}

#subreddit-right-rail__partial .py-md .py-md{
 box-shadow:0px 0px 28px 0px #333d42;
}

#subreddit-right-rail__partial > .py-md{
 background-color:#ffffff;
 box-shadow:0px 0px 50px 0px #2db9ff inset;
}

/* User drawer content */
#user-drawer-content{
 box-shadow:0px 0px 23px 0px #ffd493 inset;
 background-image:linear-gradient(141deg, #ffffff 0%, #e5f6ff 100%);
 transform:translatex(0px) translatey(0px);
}

/* Hover */
#darkmode-list-item .hover\:bg-neutral-background-hover{
 background-color:rgba(163,221,255,0.48);
 box-shadow:0px 0px 27px 0px #21272a;
}
}

@-moz-document url-prefix("https://old.reddit.com/"), url-prefix("https://old.reddit.com/r/") {
/* Header bottom left */
#header-bottom-left{
	background-image:linear-gradient(-180deg, #ffffff 0%, #c6eeff 48%, #a3e0ff 50%, #89dfff 100%);
}

.tabmenu li .choice{
	box-shadow:0px 0px 13px -8px #7ffffa inset;
	border-top-left-radius:4px;
	border-top-right-radius:4px;
	border-bottom-right-radius:0px;
}

body{
	background-color:#ffffff;
	background-image:linear-gradient(-180deg, #ffffff 0%, #5bd3ff 100%);
	background-size:auto;
	background-attachment:fixed;
}

#siteTable .linkflair .entry .top-matter > .title{
	color:#000000;
}

#siteTable .title .may-blank{
	color:#000000;
	box-shadow:none;
}

#siteTable .thing .expando-button{
	background-image:url("https://www.redditstatic.com/sprite-expando.69EqpDZz3HM.png");
}

#sr-header-area .sr-list{
	background-image:linear-gradient(-180deg, #ffffff 0%, #c6eeff 48%, #a3e0ff 50%, #89dfff 100%);
}

#sr-header-area .dropdown{
	background-image:linear-gradient(-180deg, #ffffff 0%, #c6eeff 48%, #a3e0ff 50%, #89dfff 100%);
}

#sr-more-link{
	background-image:linear-gradient(-180deg, #ffffff 0%, #c6eeff 48%, #a3e0ff 50%, #89dfff 100%);
}

#redesign-beta-optin-btn{
	background-image:linear-gradient(-180deg, #ffffff 0%, #ffecc6 48%, #fee4a4 50%, #ffd089 100%);
	color:#000000 !important;
}

.expando .usertext-body .md{
	background-image:linear-gradient(-180deg, #ffffff 0%, #c6c6c6 100%);
	box-shadow:0px 0px 10px 0px #222222 inset;
}

.usertext-edit .md textarea{
	background-image:linear-gradient(-180deg, #ffffff 0%, #c6c6c6 100%);
	box-shadow:0px 0px 10px 0px #000000 inset;
}

.bottom-area .usertext-buttons .save{
	box-shadow:0px 0px 12px 0px #7fffeb inset;
	border-bottom-width:6px;
	border-top-width:0px;
	border-left-width:0px;
	border-bottom-color:#a8ffef;
	border-right-width:0px;
}

.commentarea .nestedlisting .noncollapsed{
	box-shadow:0px 0px 8px 0px #000000 inset;
	background-color:#ffffff;
}

#siteTable .stickied{
	background-image:linear-gradient(-180deg, #ededed 0%, #ffffff 30%, #c4c4c4 100%);
	box-shadow:0px 0px 13px 0px #332233;
}

.submit-link .morelink a{
	box-shadow:0px 0px 13px 0px #000000 inset;
}

#search input[type=text]{
	background-image:linear-gradient(-180deg, #ffffff 0%, #e0e0e0 100%);
}

#form-t1_na98feu2ct .may-blank-within{
	background-image:linear-gradient(-180deg, #ededed 0%, #ffffff 30%, #c4c4c4 100%);
}

#siteTable .noncollapsed .entry{
	transform:translatex(0px) translatey(0px);
}

/* Site table */
#siteTable{
	background-image:linear-gradient(-180deg, #ffffff 0%, #e0e0e0 100%);
	background-attachment:fixed;
	
}
}

@-moz-document url-prefix("https://old.reddit.com/r/") {
/* Header bottom left */
#header-bottom-left{
	background-color:rgba(0,0,0,0);
	background-image:none !important;
}
}
